//! The command system: every browser function is one [`Command`].
//!
//! A command is a unit struct implementing [`Command`]: a dotted `NAME` (`"tabs.list"`), typed
//! `Args` and `Output` (their JSON Schemas are generated by `schemars`), some [`Meta`] data and an
//! async `run`. The [`Registry`] stores all commands type-erased (JSON in, JSON out), so every API
//! surface — MCP, REST, WebSocket JSON-RPC, scripts, the Ctrl+K palette, the keymap — can list
//! and call them without knowing their Rust types.
//!
//! Writing a command:
//!
//! ```
//! use bmcp_core::command::{CmdError, Command, Ctx, Meta, Toolset};
//! use schemars::JsonSchema;
//! use serde::{Deserialize, Serialize};
//!
//! pub struct Echo;
//!
//! #[derive(Deserialize, JsonSchema)]
//! #[serde(deny_unknown_fields)]
//! pub struct EchoArgs {
//!     /// Text to send back.
//!     pub text: String,
//! }
//!
//! #[derive(Serialize, JsonSchema)]
//! pub struct EchoOutput {
//!     pub text: String,
//! }
//!
//! impl Command for Echo {
//!     const NAME: &'static str = "system.echo";
//!     type Args = EchoArgs;
//!     type Output = EchoOutput;
//!
//!     fn meta() -> Meta {
//!         Meta::new("Return the given text.", Toolset::System)
//!     }
//!
//!     async fn run(_ctx: Ctx, args: EchoArgs) -> Result<EchoOutput, CmdError> {
//!         Ok(EchoOutput { text: args.text })
//!     }
//! }
//! ```
//!
//! Rules (checked by [`Registry::add`]): `NAME` is lowercase dotted (`group.action`), and both
//! `Args` and `Output` are structs (JSON objects) — MCP requires object schemas. Use [`Empty`]
//! when there are no arguments.

