/// One browser function. See the [module docs](self) for an example.
pub trait Command: Send + Sync + 'static {
    /// Dotted name, e.g. `"tabs.list"`. On MCP it becomes [`wire_name`] `"tabs_list"`.
    const NAME: &'static str;
    /// Arguments, deserialized from a JSON object. Use `#[serde(deny_unknown_fields)]` so typos
    /// like `tab_id` are reported instead of silently ignored.
    type Args: DeserializeOwned + JsonSchema + Send + 'static;
    /// Result, serialized to a JSON object.
    type Output: Serialize + JsonSchema + Send + 'static;

    /// Description, toolset, palette entry, … (see [`Meta`]).
    fn meta() -> Meta;

    /// The tab these arguments explicitly target, for the lock check (only done when
    /// `meta().mutates_tab` is true). Return `None` when no tab is given; a command that then
    /// picks a default tab should do it with [`Ctx::resolve_tab`], which checks the lock too.
    fn target_tab(_args: &Self::Args) -> Option<TabId> {
        None
    }

    /// Do the work. `ctx` says who is calling and gives access to the browser.
    fn run(
        ctx: Ctx,
        args: Self::Args,
    ) -> impl Future<Output = Result<Self::Output, CmdError>> + Send;
}

/// Static facts about a command, used by the API surfaces and the UI.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct Meta {
    /// One or two sentences for the AI/tool list; say what it returns.
    pub description: &'static str,
    /// Which group it belongs to; MCP exposes only `core` by default.
    pub toolset: Toolset,
    /// True when it changes an existing tab (navigates, clicks, types…). Such commands go
    /// through the tab-lock check.
    pub mutates_tab: bool,
    pub sensitivity: Sensitivity,
    /// Title in the Ctrl+K palette; `None` = not shown there.
    pub palette: Option<&'static str>,
    /// Default shortcuts like `"ctrl+shift+t"`; users override them in `keymap.json`.
    pub default_keys: &'static [&'static str],
}

impl Meta {
    /// Read-only, not mutating, not in the palette, no keys. Adjust with the builder methods:
    /// `Meta::new("…", Toolset::Core).mutates_tab().act().palette("Go to URL…")`.
    pub fn new(description: &'static str, toolset: Toolset) -> Self {
        Meta {
            description,
            toolset,
            mutates_tab: false,
            sensitivity: Sensitivity::Read,
            palette: None,
            default_keys: &[],
        }
    }

    pub fn mutates_tab(mut self) -> Self {
        self.mutates_tab = true;
        self
    }

    /// Mark as [`Sensitivity::Act`] (has side effects).
    pub fn act(mut self) -> Self {
        self.sensitivity = Sensitivity::Act;
        self
    }

    /// Mark as [`Sensitivity::Secret`] (returns or uses secrets).
    pub fn secret(mut self) -> Self {
        self.sensitivity = Sensitivity::Secret;
        self
    }

    pub fn palette(mut self, title: &'static str) -> Self {
        self.palette = Some(title);
        self
    }

    pub fn keys(mut self, keys: &'static [&'static str]) -> Self {
        self.default_keys = keys;
        self
    }
}

/// Groups of commands. MCP clients pick them with `/mcp?toolsets=net,record`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Toolset {
    Core,
    Net,
    Record,
    Script,
    Run,
    Profile,
    Stealth,
    Data,
    Ai,
    Ui,
    System,
    /// Internal commands (UI plumbing, tests): only listed when asked for explicitly.
    Hidden,
}

impl Toolset {
    pub const ALL: [Toolset; 12] = [
        Toolset::Core,
        Toolset::Net,
        Toolset::Record,
        Toolset::Script,
        Toolset::Run,
        Toolset::Profile,
        Toolset::Stealth,
        Toolset::Data,
        Toolset::Ai,
        Toolset::Ui,
        Toolset::System,
        Toolset::Hidden,
    ];

    pub fn as_str(self) -> &'static str {
        match self {
            Toolset::Core => "core",
            Toolset::Net => "net",
            Toolset::Record => "record",
            Toolset::Script => "script",
            Toolset::Run => "run",
            Toolset::Profile => "profile",
            Toolset::Stealth => "stealth",
            Toolset::Data => "data",
            Toolset::Ai => "ai",
            Toolset::Ui => "ui",
            Toolset::System => "system",
            Toolset::Hidden => "hidden",
        }
    }
}

impl fmt::Display for Toolset {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

/// Parses `"net"` → `Toolset::Net` (e.g. from `?toolsets=net,record`).
impl FromStr for Toolset {
    type Err = CmdError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        Toolset::ALL
            .into_iter()
            .find(|t| t.as_str() == s.trim())
            .ok_or_else(|| CmdError::invalid_params(format!("unknown toolset '{s}'")))
    }
}

/// How risky a command is; used for MCP annotations and approval prompts.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Sensitivity {
    /// Only reads state.
    Read,
    /// Changes something (navigates, clicks, opens tabs…).
    Act,
    /// Reads or uses secrets (passwords, cookies, API keys).
    Secret,
}

/// Who is calling a command. Recorded in events and used by the lock policy.
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum Caller {
    /// The browser's own UI (buttons, menus, Ctrl+K palette).
    Ui,
    /// An MCP client session; `agent` is the agent name when known.
    Mcp {
        session: String,
        agent: Option<String>,
    },
    Rest,
    Ws {
        conn: u64,
    },
    Script {
        id: String,
    },
    /// The built-in AI agent.
    Agent {
        id: String,
    },
    /// A step of a batch run.
    Job {
        run: String,
        step: u32,
    },
    /// A keyboard shortcut.
    Keymap,
}

/// Everything a command may use while running. Cheap to clone.
#[derive(Clone)]
pub struct Ctx {
    pub caller: Caller,
    pub backend: Arc<dyn BrowserBackend>,
    pub events: EventBus,
    /// Shared services that live longer than one call (see [`Extensions`]). The registry
    /// sets this to its own map for every call, so state survives between calls.
    pub extensions: Arc<Extensions>,
    // Set by the registry for each call.
    lock: Arc<dyn LockPolicy>,
    guards: Arc<Vec<Arc<dyn CommandGuard>>>,
    mutates_tab: bool,
    call_id: u64,
}

impl Ctx {
    /// Build the context for one call. The API layer does this per request; the registry fills
    /// in the lock policy when it runs the command.
    pub fn new(caller: Caller, backend: Arc<dyn BrowserBackend>, events: EventBus) -> Self {
        Ctx {
            caller,
            backend,
            events,
            extensions: Arc::new(Extensions::new()),
            lock: Arc::new(AllowAll),
            guards: Arc::new(Vec::new()),
            mutates_tab: false,
            call_id: 0,
        }
    }

    /// Number of this call (1, 2, 3… per registry); the same value appears in the
    /// `command.started` / `command.finished` events. 0 outside a registry call.
    pub fn call_id(&self) -> u64 {
        self.call_id
    }

    /// `Some(tab)` → that tab. `None` → the most recently opened tab (highest id), or `NO_TABS`.
    ///
    /// When the running command mutates tabs, a default-picked tab is lock-checked here (an
    /// explicit tab was already checked by the registry via [`Command::target_tab`]).
    pub async fn resolve_tab(&self, tab: Option<TabId>) -> Result<TabId, CmdError> {
        if let Some(tab) = tab {
            return Ok(tab);
        }
        let tab = self
            .backend
            .list_tabs()
            .await?
            .into_iter()
            .map(|t| t.id)
            .max()
            .ok_or_else(|| CmdError::from(crate::backend::BackendError::NoTabs))?;
        if self.mutates_tab {
            self.lock.check(&self.caller, Some(tab))?;
        }
        Ok(tab)
    }
}

impl fmt::Debug for Ctx {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Ctx")
            .field("caller", &self.caller)
            .field("call_id", &self.call_id)
            .field("mutates_tab", &self.mutates_tab)
            .finish_non_exhaustive()
    }
}

/// Arguments/output for commands that take or return nothing: `{}`.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct Empty {}

/// MCP/Anthropic tool name for a dotted command name: `"tabs.list"` → `"tabs_list"`
/// (the Anthropic API rejects dots in tool names).
pub fn wire_name(name: &str) -> String {
    name.replace('.', "_")
}
